import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<Produk> produk = Arrays.asList(
                new Produk("Kopi Susu", "minuman", 18000),
                new Produk("Roti Bakar", "makanan", 15000),
                new Produk("Teh Manis", "minuman", 8000),
                new Produk("Nasi Goreng", "makanan", 22000),
                new Produk("Es Jeruk", "minuman", 10000));

        List<String> minuman = produk.stream()
                .filter(p -> p.getKategori().equals("minuman"))
                .map(Produk::getNama)
                .collect(Collectors.toList());
        System.out.println(minuman);

        String termurah = produk.stream()
                .min(Comparator.comparing(Produk::getHarga))
                .map(Produk::getNama)
                .orElse("-");
        System.out.println("Termurah: " + termurah);

        List<String> urutHarga = produk.stream()
                .sorted(Comparator.comparing(Produk::getHarga).reversed())
                .limit(2)
                .map(p -> p.getNama() + " " + p.getHarga())
                .collect(Collectors.toList());
        System.out.println(urutHarga);
    }
}

class Produk {
    private String nama;
    private String kategori;
    private int harga;

    Produk(String nama, String kategori, int harga) {
        this.nama = nama;
        this.kategori = kategori;
        this.harga = harga;
    }

    String getNama() {
        return nama;
    }

    String getKategori() {
        return kategori;
    }

    int getHarga() {
        return harga;
    }
}

